                        for (int x = lo; x <= hi; x++)
                        {
                            double t = (x - a.x) / (b.x - a.x);
                            if (t > 0 && t < 1)
                                levels.Add(a.y + t * (b.y - a.y));
                        }
                    }
                }

            for (int y = y0; y <= y0 + height; y++)
                levels.Add(y);
            for (int i = 0; i < edges.Count; i++)
                for (int j = i + 1; j < edges.Count; j++)
                {
                    var a = edges[i];
                    var b = edges[j];
                    var r = Sub(a.b, a.a);
                    var s = Sub(b.b, b.a);
                    double den = Cross(r, s);
                    if (den == 0)
                        continue;
                    var q = Sub(b.a, a.a);
                    double t = Cross(q, s) / den, u = Cross(q, r) / den;
                    if (t > 0 && t < 1 && u > 0 && u < 1)
                    {
                        levels.Add(a.a.y + t * r.y);
                        LastCrossings++;
                    }
                }

            levels.Sort();
            LastEvents = levels.Count;
            var result = new double[width * height];
            var crossings = new List<Crossing>(edges.Count);
            for (int band = 0; band + 1 < levels.Count; band++)
            {
                double lo = levels[band], hi = levels[band + 1], dy = hi - lo;
                if (!(dy > 0))
                    continue;
                bool integrate = dy > 1e-12;
                double middle = (lo + hi) * .5;
                int row = (int)Math.Floor(middle);
                if (row < y0 || row >= y0 + height)
                    continue;
                negative?.BeginBand(lo, hi);
                observer?.Begin(lo, hi);
                crossings.Clear();
                for (int i = 0; i < edges.Count; i++)
                {
                    var e = edges[i];
                    if ((e.a.y <= middle && middle < e.b.y) || (e.b.y <= middle && middle < e.a.y))
                        crossings.Add(new Crossing{x = e.X(middle), edge = i, delta = e.b.y > e.a.y ? 1 : -1});
                }

                crossings.Sort((a, b) =>
                {
                    int c = a.x.CompareTo(b.x);
                    return c != 0 ? c : a.edge.CompareTo(b.edge);
                });
                int winding = 0, left = -1;
                foreach (var crossing in crossings)
                {
                    int before = winding;
                    winding -= crossing.delta;
                    if (before <= 0 && winding > 0)
                        left = crossing.edge;
                    else if (before > 0 && winding <= 0)
                    {
                        var l = edges[left];
                        var r = edges[crossing.edge];
                        double lm = l.X(middle), rm = r.X(middle);
                        int first = Math.Max(x0, (int)Math.Floor(lm)), last = Math.Min(x0 + width - 1, (int)Math.Floor(rm));
                        double l0 = l.X(lo), l1 = l.X(hi), r0 = r.X(lo), r1 = r.X(hi);
