                            if (integrate)
                                result[(row - y0) * width + x - x0] += dy * (a + b) * .5;
                        }
                    }
                }

                negative?.EndBand();
                observer?.End();
                if (winding != 0)
                    throw new InvalidOperationException("511 control graph winding is not closed");
            }

            var output = new float[result.Length];
            for (int i = 0; i < output.Length; i++)
                output[i] = (float)Math.Max(0, Math.Min(1, result[i]));
            return output;
        }

