                    if (den == 0)
                        continue;
                    var q = Sub(b.a, a.a);
                    double t = Cross(q, s) / den, u = Cross(q, r) / den;
                    if (t > 0 && t < 1 && u > 0 && u < 1)
                    {
                        levels.Add(a.a.y + t * r.y);
                        LastCrossings++;
                    }
                }

            levels.Sort();
            LastEvents = levels.Count;
            var result = new double[width * height];
            var crossings = new List<Crossing>(edges.Count);
            for (int band = 0; band + 1 < levels.Count; band++)
            {
                double lo = levels[band], hi = levels[band + 1], dy = hi - lo;
                if (!(dy > 0))
                    continue;
                bool integrate = dy > 1e-12;
                double middle = (lo + hi) * .5;
                int row = (int)Math.Floor(middle);
                if (row < y0 || row >= y0 + height)
                    continue;
                negative?.BeginBand(lo, hi);
                observer?.Begin(lo, hi);
                crossings.Clear();
                for (int i = 0; i < edges.Count; i++)
                {
                    var e = edges[i];
                    if ((e.a.y <= middle && middle < e.b.y) || (e.b.y <= middle && middle < e.a.y))
                        crossings.Add(new Crossing{x = e.X(middle), edge = i, delta = e.b.y > e.a.y ? 1 : -1});
                }

                crossings.Sort((a, b) =>
                {
                    int c = a.x.CompareTo(b.x);
                    return c != 0 ? c : a.edge.CompareTo(b.edge);
                });
                int winding = 0, left = -1;
                foreach (var crossing in crossings)
                {
                    int before = winding;
                    winding -= crossing.delta;
                    if (before <= 0 && winding > 0)
                        left = crossing.edge;
                    else if (before > 0 && winding <= 0)
                    {
                        var l = edges[left];
                        var r = edges[crossing.edge];
                        double lm = l.X(middle), rm = r.X(middle);
                        int first = Math.Max(x0, (int)Math.Floor(lm)), last = Math.Min(x0 + width - 1, (int)Math.Floor(rm));
                        double l0 = l.X(lo), l1 = l.X(hi), r0 = r.X(lo), r1 = r.X(hi);
                        negative?.Positive(l0, l1, r0, r1, l.sourceId, r.sourceId);
                        observer?.Positive(l0, l1, r0, r1, l.sourceId, r.sourceId);
                        for (int x = first; x <= last; x++)
                        {
                            double a = Math.Max(0, Math.Min(x + 1, r0) - Math.Max(x, l0)), b = Math.Max(0, Math.Min(x + 1, r1) - Math.Max(x, l1));
                            if (integrate)
                                result[(row - y0) * width + x - x0] += dy * (a + b) * .5;
                        }
                    }
                }

                negative?.EndBand();
                observer?.End();
                if (winding != 0)
                    throw new InvalidOperationException("511 control graph winding is not closed");
            }

            var output = new float[result.Length];
            for (int i = 0; i < output.Length; i++)
                output[i] = (float)Math.Max(0, Math.Min(1, result[i]));
            return output;
        }

        public static void Fixtures()
        {
            P[] R(double x, double y, double xx, double yy, bool reverse = false)
            {
                var r = new[]{new P(x, y), new P(xx, y), new P(xx, yy), new P(x, yy)};
                if (reverse)
                    Array.Reverse(r);
                return r;
            }

            void Check(string name, P[][] rings, double expected)
            {
                double sum = 0;
                foreach (float a in Compute(rings, 0, 0, 4, 4))
                    sum += a;
                if (Math.Abs(sum - expected) > 1e-7)
                    throw new Exception(name + " area=" + sum + " expected=" + expected);
            }

            Check("one", new[]{R(0, 0, 1, 1)}, 1);
            Check("duplicate", new[]{R(0, 0, 1, 1), R(0, 0, 1, 1)}, 1);
            Check("overlap", new[]{R(0, 0, 2, 2), R(1, 0, 3, 2)}, 6);
            Check("hole", new[]{R(0, 0, 3, 3), R(1, 1, 2, 2, true)}, 8);
            Check("outside-negative", new[]{R(0, 0, 1, 1), R(2, 2, 3, 3, true)}, 1);
            Check("touch", new[]{R(0, 0, 1, 1), R(1, 1, 2, 2)}, 2);
            Check("crossed-graph", new[]{new[]{new P(0, 0), new P(1, 1), new P(0, 1), new P(1, 0)}}, .25);
            Check("fractional-grid-crossing", new[]{new[]{new P(.1, .1), new P(2.9, .2), new P(.2, 2.9)}}, 3.915);
        }
    }

    public struct P
    {
        public double x, y;
        public P(double x, double y)
        {
            this.x = x;
            this.y = y;
        }
    }

    struct Edge
    {
        public P a, b;
        public long sourceId;
        public double X(double y) => a.x + (y - a.y) * (b.x - a.x) / (b.y - a.y);
    }

    struct Crossing
    {
        public double x;
        public int edge, delta;
    }

    // Exact band/cell fragments of the complementary region, including exterior.
    public sealed class Observer573
    {
        public struct Span
        {
            public double lo, hi, l0, l1, r0, r1;
            public long left, right;
            public int x, y;
        }

        struct PositiveSpan
        {
            public double l0, l1, r0, r1;
            public long left, right;
        }

        readonly int x0, width;
        double lo, hi;
        readonly List<PositiveSpan> positive = new();
        public readonly List<Span> atoms = new();
        public Observer573(int x0, int width)
        {
            this.x0 = x0;
            this.width = width;
        }

        public void Begin(double lo, double hi)
        {
            this.lo = lo;
            this.hi = hi;
            positive.Clear();
        }

        public void Positive(double l0, double l1, double r0, double r1, long left, long right)
        {
            positive.Add(new PositiveSpan{l0 = l0, l1 = l1, r0 = r0, r1 = r1, left = left, right = right});
        }

        void Emit(double l0, double l1, double r0, double r1, long left, long right)
        {
            if ((r0 + r1 - l0 - l1) * .5 <= 0)
                return;
            int row = (int)Math.Floor((lo + hi) * .5), first = Math.Max(x0, (int)Math.Floor((l0 + l1) * .5)), last = Math.Min(x0 + width - 1, (int)Math.Floor((r0 + r1) * .5));
            for (int x = first; x <= last; x++)
            {
                double a = Math.Max(x, Math.Min(x + 1, l0)), b = Math.Max(x, Math.Min(x + 1, l1)), c = Math.Max(x, Math.Min(x + 1, r0)), d = Math.Max(x, Math.Min(x + 1, r1));
                if ((hi - lo) * (c + d - a - b) * .5 > 0)
                    atoms.Add(new Span{lo = lo, hi = hi, l0 = a, l1 = b, r0 = c, r1 = d, left = left, right = right, x = x, y = row});
            }
        }

        public void End()
        {
            double cursor0 = x0, cursor1 = x0;
            long owner = long.MinValue;
            foreach (var p in positive)
            {
                Emit(cursor0, cursor1, p.l0, p.l1, owner, p.left);
                cursor0 = p.r0;
                cursor1 = p.r1;
                owner = p.right;
            }

            Emit(cursor0, cursor1, x0 + width, x0 + width, owner, long.MinValue + 1);
        }
    }

    public struct Span
    {
        public double lo, hi, l0, l1, r0, r1;
        public long left, right;
        public int x, y;
    }

    struct PositiveSpan
    {
        public double l0, l1, r0, r1;
        public long left, right;
    }
}
